import{_ as o,C as n,o as e,c as i,a2 as l,b as s,w as a,a as E,E as d,a3 as A}from"./chunks/framework.BODD28Fk.js";const B="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",p=JSON.parse('{"title":"일반 문서 관리","description":"","frontmatter":{},"headers":[],"relativePath":"document/index.md","filePath":"document/index.md","lastUpdated":1793459614000}'),C={name:"document/index.md"};function g(c,t,h,u,_,m){const r=n("Mermaid");return e(),i("div",null,[t[1]||(t[1]=l('<h1 id="일반-문서-관리" tabindex="-1">일반 문서 관리 <a class="header-anchor" href="#일반-문서-관리" aria-label="Permalink to &quot;일반 문서 관리&quot;">​</a></h1><p>프로젝트와 관련된 각종 공문, 사업 협약서, 지침, 인허가 서류 등 일반적인 업무 자료들을 카테고리별로 안전하게 보관하고 구성원들과 공유하는 화면입니다.</p><ul><li><strong>위치</strong>: <code>문서 소송 관리 &gt; 일반 문서 관리</code></li></ul><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+B+'" alt="일반 문서 관리 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/index.png</code> 경로에 등록해 주세요.</em></p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>부동산 개발 프로젝트 진행 과정에서 발생하는 다양한 형식의 문서(보고서, 도면, 공문, 계약서 사본)와 외부 참조 웹 링크를 체계적으로 자산화합니다. 탭 형태의 직관적인 카테고리 분류를 통해 필요한 자료를 신속하게 검색할 수 있으며, 다중 첨부 파일과 파일별 용도 설명, 외부 웹 링크 등록, 그리고 개인별 중요 문서 스크랩 기능을 제공합니다.</p>',6)),(e(),s(A,null,{default:a(()=>[d(r,{id:"mermaid-24",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%221.%20%EC%B9%B4%ED%85%8C%EA%B3%A0%EB%A6%AC%20%ED%83%AD%20%EC%84%A0%ED%83%9D%3Cbr%2F%3E(%EA%B3%B5%EB%AC%B8%C2%B7%ED%98%91%EC%95%BD%C2%B7%EC%9D%B8%ED%97%88%EA%B0%80%C2%B7%EB%B3%B4%EA%B3%A0%EC%84%9C)%22%5D%20--%3E%20B%5B%222.%20%EB%AC%B8%EC%84%9C%20%EA%B2%80%EC%83%89%20%EB%B0%8F%20%EC%A0%95%EB%A0%AC%3Cbr%2F%3E(%EC%A0%9C%EB%AA%A9%C2%B7%EB%82%B4%EC%9A%A9%C2%B7%EC%9E%91%EC%84%B1%EC%9E%90%20%ED%95%84%ED%84%B0)%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%223.%20%EC%83%81%EC%84%B8%20%EC%97%B4%EB%9E%8C%20%EB%B0%8F%20%EC%9E%90%EC%9B%90%20%ED%99%9C%EC%9A%A9%3Cbr%2F%3E(%EB%B3%B8%EB%AC%B8%C2%B7%EC%B2%A8%EB%B6%80%ED%8C%8C%EC%9D%BC%C2%B7%EC%B0%B8%EC%A1%B0%EB%A7%81%ED%81%AC)%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%224.%20%EC%A4%91%EC%9A%94%20%EB%AC%B8%EC%84%9C%20%EC%8A%A4%ED%81%AC%EB%9E%A9%3Cbr%2F%3E(%EA%B0%9C%EC%9D%B8%20%EB%B3%B4%EA%B4%80%ED%95%A8%20%EC%A6%90%EA%B2%A8%EC%B0%BE%EA%B8%B0)%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%225.%20%EC%8B%A0%EA%B7%9C%20%EB%AC%B8%EC%84%9C%20%EC%9E%91%EC%84%B1%C2%B7%EC%88%98%EC%A0%95%3Cbr%2F%3E(%EB%8B%A4%EC%A4%91%20%ED%8C%8C%EC%9D%BC%20%EB%B0%8F%20%EC%84%A4%EB%AA%85%20%EC%B2%A8%EB%B6%80)%22%5D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[E(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=l('<h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>카테고리 탭 분류 체계</strong>: 인허가, 사업 협약, 설계/감리, 일반 공문 등 프로젝트 성격에 맞게 정의된 카테고리별 원클릭 탭 필터링</li><li><strong>다중 파일 첨부 및 파일별 설명</strong>: 여러 개의 첨부 파일을 동시에 업로드할 수 있으며, 원본 파일명을 바꾸지 않고도 &#39;최종 승인 날인본&#39;, &#39;검토용 도면&#39; 등 세부 설명을 기재 가능</li><li><strong>외부 참조 웹 링크 연동</strong>: 지자체 고시 공고, 법령 정보, 전자공시시스템(DART) 등 온라인 외부 웹사이트 URL을 문서 자원으로 직접 등록</li><li><strong>개인 맞춤형 문서 스크랩</strong>: 자주 찾아보거나 중요한 문서를 &#39;내 스크랩&#39; 보관함에 담아 마이페이지 등에서 언제든 빠르게 재접근</li><li><strong>정밀한 3단 조회수(Hit) 추적</strong>: 문서 자체의 조회수뿐만 아니라, 첨부된 파일 다운로드 횟수와 외부 링크 클릭 횟수를 개별 집계하여 구성원들의 자료 활용도 파악</li><li><strong>권한 기반 열람 및 작성 제어</strong>: 프로젝트 참여 구성원 권한에 따른 안전한 문서 등록, 수정 및 삭제 통제</li></ul><h2 id="화면-구성-및-실무-가이드" tabindex="-1">화면 구성 및 실무 가이드 <a class="header-anchor" href="#화면-구성-및-실무-가이드" aria-label="Permalink to &quot;화면 구성 및 실무 가이드&quot;">​</a></h2><h3 id="_1-목록-제어-및-검색-영역" tabindex="-1">1. 목록 제어 및 검색 영역 <a class="header-anchor" href="#_1-목록-제어-및-검색-영역" aria-label="Permalink to &quot;1. 목록 제어 및 검색 영역&quot;">​</a></h3><p>필요한 문서를 신속하게 찾기 위한 조건 필터와 카테고리 탭을 제공합니다.</p><ul><li><strong>카테고리 탭</strong>: 상단에 배치된 분류 탭(예: 전체, 인허가, 계약/협약, 공문 등)을 클릭하여 해당 분류의 문서만 즉시 선별합니다.</li><li><strong>검색 및 정렬 옵션</strong>: <ul><li><code>검색창</code>: 제목, 본문 내용, 작성자 이름으로 키워드 통합 검색</li><li><code>정렬 기준</code>: 등록일시 최신순(기본), 조회수 높은순 등으로 정렬 순서 전환</li><li><code>페이지당 표시 건수</code>: 10건, 20건, 30건, 50건 단위 선택</li></ul></li></ul><h3 id="_2-문서-목록-테이블" tabindex="-1">2. 문서 목록 테이블 <a class="header-anchor" href="#_2-문서-목록-테이블" aria-label="Permalink to &quot;2. 문서 목록 테이블&quot;">​</a></h3><p>조회된 문서의 기본 요약 정보와 첨부 자원 유무를 한눈에 확인할 수 있습니다.</p><ul><li><strong>표시 항목</strong>: 카테고리 태그, 문서 제목, 첨부 자원 아이콘(파일 아이콘 📎, 링크 아이콘 🔗), 작성자, 등록일시, 조회수</li><li><strong>첨부 자원 직관적 식별</strong>: 제목 옆에 첨부 파일 개수와 외부 링크 개수가 아이콘과 함께 표시되어, 본문에 들어가지 않고도 첨부물 유무를 즉시 알 수 있습니다.</li></ul><h3 id="_3-문서-상세-보기-view" tabindex="-1">3. 문서 상세 보기 (View) <a class="header-anchor" href="#_3-문서-상세-보기-view" aria-label="Permalink to &quot;3. 문서 상세 보기 (View)&quot;">​</a></h3><p>선택한 문서의 상세 내용과 첨부된 모든 자료를 열람하는 화면입니다.</p><ul><li><strong>본문 영역</strong>: 서식이 적용된 텍스트와 등록된 이미지, 설명문 확인</li><li><strong>첨부 파일 목록</strong>: 등록된 파일명, 파일 용량, <strong>파일별 세부 설명</strong>이 함께 표시되며, 클릭 시 즉시 다운로드됩니다. (다운로드 시 파일별 다운로드 횟수 자동 카운트)</li><li><strong>참조 링크 목록</strong>: 연계된 외부 사이트 링크가 표시되며, 클릭 시 새 창으로 연결됩니다. (클릭 시 링크별 조회수 자동 카운트)</li><li><strong>스크랩 버튼</strong>: 문서 우측 상단의 [스크랩] 아이콘을 누르면 내 개인 스크랩 목록에 즉시 추가되어 즐겨찾기처럼 활용할 수 있습니다.</li></ul><h3 id="_4-문서-작성-및-수정-form" tabindex="-1">4. 문서 작성 및 수정 (Form) <a class="header-anchor" href="#_4-문서-작성-및-수정-form" aria-label="Permalink to &quot;4. 문서 작성 및 수정 (Form)&quot;">​</a></h3><p>새로운 문서를 프로젝트 자료실에 등록하거나 기존 내용을 보완하는 폼입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">상세 설명 및 실무 팁</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>카테고리</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">문서의 성격에 맞는 분류 항목(인허가, 계약, 공문 등)을 선택합니다.</td></tr><tr><td style="text-align:left;"><strong>문서 제목</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">다른 구성원이 문서 목록에서 쉽게 식별할 수 있도록 명확한 제목을 작성합니다.</td></tr><tr><td style="text-align:left;"><strong>본문 내용</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">문서의 개요, 주요 변경 사항, 취지 등을 서식 에디터로 작성합니다.</td></tr><tr><td style="text-align:left;"><strong>첨부 파일</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">[파일 추가]를 눌러 여러 개의 문서를 첨부합니다. 각 파일마다 **&#39;파일 설명&#39;**란에 용도를 적어주면 협업 시 매우 유용합니다.</td></tr><tr><td style="text-align:left;"><strong>참조 링크</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">[링크 추가]를 눌러 관련 웹사이트의 URL 주소와 링크 제목을 등록합니다.</td></tr></tbody></table><h2 id="💡-실무-활용-팁" tabindex="-1">💡 실무 활용 팁 <a class="header-anchor" href="#💡-실무-활용-팁" aria-label="Permalink to &quot;💡 실무 활용 팁&quot;">​</a></h2><ul><li><strong>파일 설명 필드의 적극 활용</strong>: 파일명이 난해한 스캔 파일(예: <code>Scan_20261027_001.pdf</code>)이라도 업로드 시 파일 설명에 **&quot;건축허가 표지 및 조건부 승인 통보서&quot;**와 같이 실무 명칭을 적어두면 동료들이 다운로드하지 않고도 파일 내용을 바로 파악할 수 있습니다.</li><li><strong>외부 법령 및 지자체 고시 연동</strong>: 인허가 조건이나 조례 개정안처럼 웹상에 공시된 자료는 파일로 저장해 두면 최신 내용과 달라질 수 있습니다. 이 경우 &#39;참조 링크&#39; 기능으로 지자체 고시 웹페이지를 직접 연결해 두면 항상 최신 공시 정보를 참조할 수 있습니다.</li><li><strong>문서 수정 시 기존 파일 보존</strong>: 문서 내용을 보완하거나 추가 파일을 등록할 때, 기존에 등록된 파일들은 삭제하지 않는 한 그대로 유지되므로 안심하고 수정 작업을 진행할 수 있습니다.</li></ul>',17))])}const f=o(C,[["render",g]]);export{p as __pageData,f as default};
